    text: "Pierwsze w historii zdjęcie czarnej dziury (2019) pokazało obiekt w galaktyce M87, oddalony o 55 milionów lat świetlnych. Powstało dzięki połączeniu radioteleskopów z całej Ziemi w jeden wirtualny instrument wielkości planety.",
