    text: "W islandzkim nowe słowa tworzy się, łącząc rodzime rdzenie zamiast pożyczać obce — komputer to 'tölva' (tala = liczba + völva = wieszczka). Islandczycy świadomie tworzą neologizmy, by nie zaśmiecać języka anglicyzmami.",
