    text: "Usain Bolt ustanowił rekord świata 100 m (9,58 s) w 2009 r. Jego prędkość maksymalna wyniosła ok. 44,72 km/h. W tym biegu zrobił tylko 41 kroków — dłuższych niż u innych sprinterów bo mierzy ok. 195 cm.",
    category: "sports",
    emoji: "🏃",
