    text: "Sumo jest sportem w Japonii, a zarazem sztuką walki z bogatą tradycją religijną. Turniej trwa 15 dni i odbywa się 6 razy w roku, a awans i degradacja zależą od wyników. Yokozuna (najwyższa ranga) to tytuł dożywotni — nie można go stracić.",
    category: "sports",
    emoji: "🤼",
