    text: "Tour de France to jeden z najtrudniejszych wyścigów kolarskich na świecie — ok. 3500 km w 3 tygodnie. Kolarze pokonują dziennie ok. 180 km i spalają ok. 8000 kalorii — jedzą niemal bez przerwy, by uniknąć 'ściany' energetycznej.",
    category: "sports",
    emoji: "🚴",
