    id: "spt51",
    text: "Rywalizacja piłkarska Real Madryt vs FC Barcelona (El Clasico) jest jednym z najbardziej oglądanych regularnych spotkań sportowych na świecie — według szacunków ogląda je kilkaset milionów widzów.",
