    id: "kid32",
    text: "Plaskie robaki (planarie) są superbohaterami świata zwierząt — jeśli potniesz je na kilka kawalków, z każdego kawałka wyrosnie nowy pełny robak! Mogą nawet wyhodować nową głowę! Naukowcy badają planarie by zrozumieć regeneracje.",
    category: "kids",
    emoji: "🪱",
