    text: "Psy wyjątkowo dobrze 'czytają' ludzkie emocje z twarzy. Psy rozumieją gest wskazywania palcem — szympansom przychodzi to znacznie trudniej. Współewoluowaliśmy razem przez ok. 15 000-40 000 lat.",
