    text: "Bazyliszek płatkogłowy może biegać po powierzchni wody dzięki szybkości i specjalnej budowie stóp. Porusza się ok. 1,5 m/s — gdyby zwolnił, zacząłby tonąć. Dlatego nazywa się go 'jaszczurką Jezusa'.",
