    text: "Ciecze nienewtonowskie zachowują się wbrew intuicji. Zawiesina mąki ziemniaczanej w wodzie twardnieje pod uderzeniem, a płynie pod delikatnym naciskiem — można po niej biegać po powierzchni, ale stojąc w miejscu, powoli się w niej zapadasz.",
    category: "science",
    emoji: "♾️",
