    text: "Skala Richtera mierzy energię trzęsień ziemi logarytmicznie — każdy stopień oznacza 31,6 razy więcej energii. Trzęsienie 7.0 wyzwala ok. 1000 razy więcej energii niż 5.0. Najsilniejsze zarejestrowane trzęsienie (Chile 1960) miało magnitudę 9,5.",
    category: "science",
    emoji: "📊",
