    text: "Chlorofil absorbuje głównie czerwone i niebieskie światło, a odbija zielone — dlatego rośliny są zielone. Jednak w głębszych warstwach wody, gdzie czerwone światło nie dociera, algi używają innych pigmentów — stąd czerwone i brązowe wodorosty.",
