    text: "Masło orzechowe zostało opatentowane w 1884 r. przez Marcellusa Edsona w Kanadzie, a później przez Johna Kellogga (tegoż od płatków śniadaniowych) w USA. Pierwotnie było zalecane jako zdrowy pokarm dla osób bez zębów.",
