    text: "Miasto Wenecja zbudowano na 118 wyspach na lagunie. Jej fundamenty to pale drewniane wbite w mulisty grunt — drewno pod wodą nie gnije, bo nie ma tlenu. Wenecja tonie o ok. 1-2 mm rocznie i jednocześnie poziom morza rośnie.",
