    text: "Każda komórka człowieka (oprócz czerwonych krwinek) zawiera kompletny zapis DNA — ok. 3 miliardy par zasad. Gdybyś wydrukował DNA z jednej komórki czcionką 1-punktową, książka miałaby 2 miliony stron.",
