    text: "Ludzkie ucho słyszy dźwięki od 20 Hz do 20 000 Hz — ale tylko w młodości. Z wiekiem tracimy zdolność słyszenia wysokich częstotliwości. Dźwięk 'Mosquito' (17 500 Hz) jest słyszalny tylko przez osoby poniżej ok. 25 roku życia.",
    category: "human",
    emoji: "👂",
