    text: "Seryjny zabójca H.H. Holmes wybudował w Chicago specjalny 'zamek mordercy' na Wystawę Światowa 1893 — hotel z tajnymi korytarzami, pokojami bez okien, komorami gazowymi i piecami do spalania ciał. Szacuje się że zamordował od 27 do ponad 200 osób. Budynek spłonął w 1895.",
