    text: "Pablo Escobar w szczytowym okresie zarabiał 420 milionów dolarów tygodniowo. Wydawal 2500 dolarów miesięcznie tylko na gumki recepturki do paczek gotówki. Szacuje się ze 10% jego zapasów gotówki było co roku zjadane przez szczury lub gniło zanim zdążono je wydac.",
    category: "crime",
