    text: "Krucjaty nie były prostym konfliktem religijnym chrześcijanie-muzułmanie. Chrześcijanie atakowali również innych chrześcijan (szczególnie podczas IV Krucjaty, która splądrowała Konstantynopol w 1204). Muzułmanie często współpracowali z krzyzowcami przeciw innym muzulmanom. Lokalna polityka i ekonomia grały równie ważną role co religia.",
