    text: "Wikingowie nie wierzyli w życie wieczne w Valhalli dla wszystkich — tylko ci, którzy zginęli w walce trafiali do Valhalli. Reszta trafiała do Hel (nie piekło — po prostu mroczna kraina umarłych). Wielu Wikingów wcale nie było wojownikami — byli rolnikami i kupcami. Mit Wikinga-wojownika jest produktem XIX-wiecznego romantyzmu.",
