    text: "Reformacja Lutra zaczęła się nie od przybicia 95 też do drzwi — to prawdopodobnie legendarna opowieść. Luter wysłał tezy listem do arcybiskupa Moguncji. Drukarz (bez zgody Lutra) wydrukował je i rozesłał po Europie. Bez prasy drukarskiej Gutenberga tezy byłby zapomniane — druk był prawdziwym motorem Reformacji.",
